"""Generate the current assignment write-ups from validated V3/V4 evidence."""
from pathlib import Path
import json
import sys
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.platypus import SimpleDocTemplate,Paragraph,Table,TableStyle,PageBreak,Spacer
from pypdf import PdfReader
sys.path.insert(0,str(Path.cwd()))
from chorus_hit.artifacts import load_run

ROOT=Path.cwd();OUT=ROOT/'docs'
old=load_run('v3_nested_001');new=load_run('v4_std74_001')
comparison=json.loads((ROOT/'results/research_v4/comparison.json').read_text())
assert comparison['metrics_after']['balanced_accuracy']==new.summary['metrics']['balanced_accuracy']
assert comparison['metrics_before']['balanced_accuracy']==old.summary['metrics']['balanced_accuracy']
assert not new.summary['target_status']['target_met_in_this_evaluation']
styles=getSampleStyleSheet()
navy=colors.HexColor('#17323C');teal=colors.HexColor('#127C80');soft=colors.HexColor('#E7F0F0');muted=colors.HexColor('#53666E')
styles.add(ParagraphStyle(name='ProjectTitleNew',fontName='Helvetica-Bold',fontSize=20,leading=24,textColor=navy,spaceAfter=6))
styles.add(ParagraphStyle(name='KickerNew',fontName='Helvetica-Bold',fontSize=9,leading=12,textColor=teal,spaceAfter=5))
styles.add(ParagraphStyle(name='SectionNew',fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=teal,spaceBefore=9,spaceAfter=5))
styles.add(ParagraphStyle(name='TextNew',fontName='Helvetica',fontSize=9.4,leading=13.4,textColor=navy,spaceAfter=6))
styles.add(ParagraphStyle(name='SmallNew',fontName='Helvetica',fontSize=8,leading=11,textColor=muted,spaceAfter=4))
def p(x,style='TextNew'):return Paragraph(x,styles[style])
def section(t):return p(t,'SectionNew')
def pct(v):return f'{100*v:.2f}%'
def table(rows,widths):
 t=Table([[p(str(v),'SmallNew') for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),soft),('LINEBELOW',(0,0),(-1,0),.7,teal),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
 return t
head=[p('Predicting Hit Songs Using Repeated Chorus','ProjectTitleNew'),p('UE24CS352A - Machine Learning mini-project | 4 October 2026','KickerNew'),p('Dhanush Sai Suprapadha (PES2UG24CS154) &nbsp;&nbsp; | &nbsp;&nbsp; Deepthi V (PES2UG24CS150)','SmallNew')]
metric_keys=['accuracy','balanced_accuracy','precision','recall','f1']
metric_labels={'accuracy':'Accuracy','balanced_accuracy':'Balanced accuracy','precision':'Precision (year-end hit)','recall':'Recall (year-end hit)','f1':'F1 score'}
metric_rows=[['Metric','Previous V3','Current V4']]+[[metric_labels[k],pct(old.summary['metrics'][k]),pct(new.summary['metrics'][k])] for k in metric_keys]
paired=comparison['paired_vs_v3'];ci=paired['ci95'];current_ci=new.summary['ci95']['balanced_accuracy']
summary=head+[section('Research question'),p('Can audio measurements from a 15-second chorus distinguish a Billboard year-end hit from another song that appeared on the weekly Hot 100? Both classes already charted. The study tests a retrospective association, not a formula for making a hit.'),section('Dataset and method'),p('We use an inherited table of 751 songs, 71 normalized artist-name groups and 518 audio measurements. The original development set contains 597 songs from 52 groups; 154 songs from 19 other groups form an already known historical test. Artist names and titles are excluded from model inputs.'),p('The current study compared 63 declared settings using five outer and three inner artist-grouped folds. Eight new settings used 74 features measuring variation in chorus audio. All learned preprocessing and model selection stayed within training folds. The final development model is balanced logistic regression with standard scaling and 74 selected features.'),section('Measured development results'),table(metric_rows,[240,135,136]),p(f'V4 balanced accuracy is <b>{pct(new.summary["metrics"]["balanced_accuracy"])}</b> (approximate 95% whole-artist interval {pct(current_ci[0])}-{pct(current_ci[1])}). Its paired change from V3 is {100*paired["balanced_accuracy_difference"]:+.2f} percentage points (interval {100*ci[0]:+.2f} to {100*ci[1]:+.2f} points). The interval includes zero, so a dependable gain is not established.'),section('Conclusion'),p('The software, grouped evaluation and demo are complete, but the observed accuracy remains modest. No fresh independent test exists, and the original matching recordings are unavailable for verifying audio extraction. The immediate research need is better recording/label evidence and a new evaluation collection.'),p('<b>Code and evidence:</b> <link href="https://github.com/DhanushSS/chorus-hit-predictor" color="#127C80">github.com/DhanushSS/chorus-hit-predictor</link>. <b>Source features:</b> <link href="https://github.com/AntoniosMalak/Predicting-Hit-Songs-Using-Repeated-Chorus" color="#127C80">Antonios Malak dataset</link> (Apache-2.0).','SmallNew')]
report=head+[section('1. Problem and motivation'),p('The goal is to measure whether short chorus audio contains useful information about stronger chart success. Class 1 is a song in the source year-end Billboard Hot 100 collection; class 0 is another song sampled from weekly Hot 100 charts. Both classes can have charted. The available labels are retrospective proxies, so this is not a prospective hit forecast or a claim that chorus sound causes popularity.'),section('2. Data and representation'),p('The inherited dataset has 751 songs from 71 normalized artist-name groups: 366 year-end hits and 385 other chart songs. Each row contains 518 summary features from 15-second chorus audio, including MFCC, chroma, RMS energy, tonnetz, spectral and zero-crossing measurements. The latest representation selects 74 standard-deviation columns that summarize within-chorus variation. Artist and title are identification/grouping metadata only.'),p('The fixed original split gives 597 development songs across 52 groups and 154 historical songs across 19 other groups. Matching original recordings, complete version identities and fully verified chart labels are not available. The historical partition was already examined in earlier work and was not reused to select V4.'),section('3. Training and evaluation'),p('The V4 experiment retained 55 V3 controls and added eight predeclared balanced logistic-regression settings using 74 standard-deviation features, two scalers and four regularization strengths. Five outer artist-grouped folds estimate the model-selection procedure; three inner artist-grouped folds choose settings. Imputation, variance filtering, scaling and any feature selection fit on training rows only. Native classifier thresholds were kept fixed.'),p('The selected final development model is logistic regression (C=0.1, balanced classes) with standard scaling and 74 features. The app accepts the original ordered 518-feature input and applies the saved selection inside the model pipeline.'),section('4. Results on the same development songs'),table(metric_rows,[240,135,136]),p(f'The paired change in balanced accuracy is {100*paired["balanced_accuracy_difference"]:+.2f} points; approximate 95% interval {100*ci[0]:+.2f} to {100*ci[1]:+.2f} points. V4 balanced accuracy interval: {pct(current_ci[0])}-{pct(current_ci[1])}. These intervals resample artist groups and condition on saved predictions. V3 and V4 reuse the same 597 previously inspected songs, so this is exploratory evidence, not an independent new test.'),PageBreak(),p('Implementation, limits and conclusion','ProjectTitleNew'),section('5. What the software does'),p('The Python project validates the ordered feature table, preserves artist-group split membership and records model settings, predictions, fold assignments and checksums. A Streamlit application provides historical-song examples, exploratory audio upload and a results view. The original baseline remains the default; V4 can be selected as a research option.'),p('The repository includes a README, pinned dependencies, data provenance, the working app, saved models and run manifests. Individual fit records are stored in compact trial archives; their original hashes remain in each manifest and are checked when a run is loaded. The latest local test suite passed 30 tests. The current presentation file is retained for later work.'),section('6. What the result means'),p('V4 increased ordinary accuracy from 53.27% to 54.61% and balanced accuracy from 53.25% to 54.66% on matched grouped development folds. It changed the final selected classifier to a 74-feature setting. The paired uncertainty interval includes zero, so these data do not establish a reliable gain. None of the five reported V4 metrics reaches 60%, the team\'s next exploratory goal.'),p('The 60% goal is not an assignment requirement. The available PDF guidelines assess quality of deliverables, working code, repository, write-up, presentation, live demonstration, Q&A and individual contribution; they do not state a numeric accuracy cutoff.'),section('7. Limitations'),p('Artist-name grouping cannot fully resolve aliases and credited collaborators. Labels and recording versions have incomplete independent verification. Original waveforms are unavailable, so live upload extraction cannot be proved equivalent to the inherited training features. Repeated use of this development set limits the strength of new improvement claims. The old 154-song set is a historical benchmark; a genuinely new locked test set is still missing.'),section('8. Conclusion and next work'),p('The project has a functioning, reproducible ML pipeline and an honest measurement of the current representation. Chorus variation shows a small exploratory increase, but the task remains difficult. To pursue 60%, the strongest next step is verified song/artist/chart evidence, permitted matching recordings and a reserved new evaluation collection before another model search.'),section('References and reproducibility'),p('[1] <link href="https://github.com/AntoniosMalak/Predicting-Hit-Songs-Using-Repeated-Chorus" color="#127C80">Feature collection and source license</link>. [2] <link href="https://cs229.stanford.edu/proj2021spr/report2/81974051.pdf" color="#127C80">Eric Liu, original repeated-chorus study</link>. [3] <link href="https://github.com/DhanushSS/chorus-hit-predictor" color="#127C80">Project code and saved evidence</link>. Local run: v4_std74_001; source configuration: configs/v4_std74.json.','SmallNew')]
def write(name,story,count):
 dest=OUT/name
 def footer(canvas,doc):
  canvas.setStrokeColor(soft);canvas.line(42,35,A4[0]-42,35)
  canvas.setFont('Helvetica',8);canvas.setFillColor(muted)
  canvas.drawString(42,22,'UE24CS352A | Chorus hit mini-project | 4 Oct 2026')
  canvas.drawRightString(A4[0]-42,22,str(doc.page))
 SimpleDocTemplate(str(dest),pagesize=A4,leftMargin=42,rightMargin=42,topMargin=37,bottomMargin=46,
  title='Predicting Hit Songs Using Repeated Chorus',author='Dhanush Sai Suprapadha; Deepthi V').build(story,onFirstPage=footer,onLaterPages=footer)
 pages=len(PdfReader(dest).pages)
 print(dest,pages)
 if pages!=count:raise ValueError(f'{name}: expected {count} pages, got {pages}')
write('Project_Summary_1_Page.pdf',summary,1)
write('Project_Report_2_Pages.pdf',report,2)
